    def norm(val):
        return str(val).lower().replace(" ", "").replace("\n", "")

    allergy_records = final_state.get("allergy_records", {})
    for record in allergy_records.values():
        if norm(record.get("patient_id")) == norm("PAT1002"):
            if norm(record.get("allergen")) == norm("Pollen") and norm(record.get("status")) == norm("active"):
                return True
    return False

